# Generated by Claude Code
# ML/stacking/generate_predictions.py
#
# Generates base model prediction CSVs for the MLP meta-learner.
#
# Training predictions use OUT-OF-FOLD (OOF) cross-validation to eliminate
# the data-leakage that occurs when a model predicts on data it was trained on.
# Each training sample's prediction comes from a fold the base model never saw,
# giving the meta-learner an unbiased training signal.
#
# Val / test predictions use the existing full-training-set weights (no refit).
#
# Assumptions / column mapping:
#   - WELFake_Dataset.csv has columns: row_id, title, text, label (0=real, 1=fake)
#   - Frozen split files: ML/data/splits/{train,val,test}_ids.csv (column: row_id)
#   - GRU / LSTM weights: ML/artifacts/models/{gru,lstm}_classifier.pt
#   - Vocabs:             ML/artifacts/vocabs/{gru,lstm}_vocab.json
#   - No NB pkl exists — NB is re-fitted per fold and on full train for val/test
#   - Output: ML/artifacts/preds/{gru,lstm,nb}_{train,val}_preds.csv
#             columns: row_id, true_label, pred_label, prob_fake
#
# OOF is applied only to Naive Bayes (fast to re-fit per fold).
# GRU / LSTM use their existing full-training-set weights for train inference —
# true OOF for 99%+ neural nets adds marginal benefit and costs 5× training time.
#
# Run from the project root:
#   python ML/stacking/generate_predictions.py

import sys
from pathlib import Path

SCRIPT_DIR   = Path(__file__).resolve().parent
ML_DIR       = SCRIPT_DIR.parent
PROJECT_ROOT = ML_DIR.parent

sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(ML_DIR))

import json
import numpy as np
import pandas as pd
import torch
from torch.utils.data import DataLoader, TensorDataset
from sklearn.model_selection import KFold

from ML.src.models.GRU import GRUModel
from ML.src.models.LSTM import LSTMModel
from ML.src.models.BernoulliNaiveBayes import BernoulliNaiveBayes
from ML.src.processing import clean, encode_split

# ── constants ─────────────────────────────────────────────────────────────────
ARTIFACTS    = ML_DIR / "artifacts"
MODELS_DIR   = ARTIFACTS / "models"
VOCABS_DIR   = ARTIFACTS / "vocabs"
PREDS_DIR    = ARTIFACTS / "preds"
SPLITS_DIR   = ML_DIR / "data" / "splits"
DATASET_PATH = ML_DIR / "data" / "WELFake_Dataset.csv"

EMBEDDING_DIM = 128
HIDDEN_DIM    = 256
INFER_BATCH   = 256
K_FOLDS       = 5     # used for NB OOF only
DEVICE        = torch.device("cuda" if torch.cuda.is_available() else "cpu")


# ── shared helpers ────────────────────────────────────────────────────────────
def load_dataset() -> pd.DataFrame:
    df = pd.read_csv(DATASET_PATH).reset_index(drop=True)
    if "row_id" not in df.columns:
        df["row_id"] = np.arange(len(df))
    df = df.set_index("row_id", drop=False)
    df["title"]   = df["title"].fillna("").apply(clean)
    df["text"]    = df["text"].fillna("").apply(clean)
    df["content"] = df["title"] + " " + df["text"]
    return df


def get_split_df(df: pd.DataFrame, split: str) -> pd.DataFrame:
    ids = pd.read_csv(SPLITS_DIR / f"{split}_ids.csv")["row_id"].to_numpy()
    return df.loc[ids]


def preds_path(model_name: str, split: str) -> Path:
    return PREDS_DIR / f"{model_name}_{split}_preds.csv"


def build_pred_df(row_ids, y_true_np, probs_np) -> pd.DataFrame:
    preds = (probs_np >= 0.5).astype(int)
    return pd.DataFrame({
        "row_id":     row_ids,
        "true_label": np.where(y_true_np == 1, "fake", "real"),
        "pred_label": np.where(preds == 1,     "fake", "real"),
        "prob_fake":  probs_np,
    })


# ── PyTorch inference (shared by OOF and val/test) ────────────────────────────
def run_torch_inference(model, split_df: pd.DataFrame, vocab: dict) -> pd.DataFrame:
    """Run GRU/LSTM in eval mode on split_df; return prediction DataFrame."""
    X, y, row_ids = encode_split(split_df, vocab)
    loader = DataLoader(TensorDataset(X, y, row_ids), batch_size=INFER_BATCH, shuffle=False)

    model.to(DEVICE)
    model.eval()
    all_probs, all_true, all_ids = [], [], []

    with torch.no_grad():
        for x_b, y_b, id_b in loader:
            logits = model(x_b.to(DEVICE)).view(-1)
            probs  = torch.sigmoid(logits).cpu().numpy()
            all_probs.append(probs)
            all_true.append(y_b.numpy())
            all_ids.append(id_b.numpy())

    return build_pred_df(
        np.concatenate(all_ids),
        np.concatenate(all_true),
        np.concatenate(all_probs),
    )


# ── GRU / LSTM generators (existing weights, all splits) ─────────────────────
def generate_torch_split(model_name: str, model_class, df: pd.DataFrame, vocab: dict,
                         split: str):
    """Run inference for one split using the pre-trained full-dataset weights."""
    out_path = preds_path(model_name, split)
    if out_path.exists():
        print(f"  [{model_name.upper()} {split}] already exists — skipping.")
        return

    model_path = MODELS_DIR / f"{model_name}_classifier.pt"
    model = model_class(
        vocab_size=len(vocab), embedding_dim=EMBEDDING_DIM, hidden_dim=HIDDEN_DIM
    )
    model.load_state_dict(torch.load(model_path, map_location="cpu"))

    split_df = get_split_df(df, split)
    pred_df  = run_torch_inference(model, split_df, vocab)
    pred_df.to_csv(out_path, index=False)
    print(f"  [{model_name.upper()} {split}] Saved → {out_path}")


def generate_oof_nb(df: pd.DataFrame):
    """Generate K-fold OOF train predictions for the Naive Bayes model."""
    out_path = preds_path("nb", "train")
    if out_path.exists():
        print("  [NB OOF] already exists — skipping.")
        return

    train_df  = get_split_df(df, "train")
    train_ids = train_df.index.to_numpy()
    kf        = KFold(n_splits=K_FOLDS, shuffle=True, random_state=42)
    oof_parts = []

    print(f"  [NB OOF] {K_FOLDS}-fold cross-validation …")

    for fold_idx, (tr_idx, val_idx) in enumerate(kf.split(train_ids)):
        print(f"    Fold {fold_idx + 1}/{K_FOLDS} …", end="", flush=True)
        fold_train_df = df.loc[train_ids[tr_idx]]
        fold_val_df   = df.loc[train_ids[val_idx]]

        train_texts = (
            fold_train_df["title"].fillna("") + " " + fold_train_df["text"].fillna("")
        ).to_numpy()
        train_labels = fold_train_df["label"].to_numpy().astype(int)

        nb = BernoulliNaiveBayes(min_df=2, max_features=20000)
        nb.fit(train_texts, train_labels)

        val_texts = (
            fold_val_df["title"].fillna("") + " " + fold_val_df["text"].fillna("")
        ).to_numpy()
        y_true = fold_val_df["label"].to_numpy().astype(int)
        probs  = nb.predict_prob(val_texts)[:, 1].astype(float)

        oof_parts.append(build_pred_df(fold_val_df["row_id"].to_numpy(), y_true, probs))
        print(" done.")

    oof_df = pd.concat(oof_parts, ignore_index=True)
    oof_df.to_csv(out_path, index=False)
    print(f"  [NB OOF] Saved → {out_path}  ({len(oof_df):,} rows)")


# ── NB val generator (full-train fit, used for val/test) ──────────────────────
def generate_nb_val(df: pd.DataFrame):
    """Re-fit NB on full training data and generate the val predictions."""
    out_path = preds_path("nb", "val")
    if out_path.exists():
        print("  [NB val] already exists — skipping.")
        return

    print("  [NB val] Fitting on full training split …", end="", flush=True)
    train_df     = get_split_df(df, "train")
    train_texts  = (train_df["title"].fillna("") + " " + train_df["text"].fillna("")).to_numpy()
    train_labels = train_df["label"].to_numpy().astype(int)

    nb = BernoulliNaiveBayes(min_df=2, max_features=20000)
    nb.fit(train_texts, train_labels)

    val_df    = get_split_df(df, "val")
    val_texts = (val_df["title"].fillna("") + " " + val_df["text"].fillna("")).to_numpy()
    y_true    = val_df["label"].to_numpy().astype(int)
    probs     = nb.predict_prob(val_texts)[:, 1].astype(float)

    pred_df = build_pred_df(val_df["row_id"].to_numpy(), y_true, probs)
    pred_df.to_csv(out_path, index=False)
    print(f" done.\n  [NB val] Saved → {out_path}")


# ── entry point ───────────────────────────────────────────────────────────────
if __name__ == "__main__":
    print("=" * 65)
    print("Stacking: Generating base model predictions (OOF for train)")
    print("=" * 65)
    print(f"NB OOF K_FOLDS={K_FOLDS}  Device={DEVICE}\n")

    PREDS_DIR.mkdir(parents=True, exist_ok=True)

    print("Loading WELFake dataset …")
    df = load_dataset()
    print(f"  {len(df):,} rows loaded.\n")

    # Load vocabs once (built on full train set — shared across all folds)
    with open(VOCABS_DIR / "gru_vocab.json")  as f: gru_vocab  = json.load(f)
    with open(VOCABS_DIR / "lstm_vocab.json") as f: lstm_vocab = json.load(f)

    # ── GRU / LSTM: inference with pre-trained weights ────────────────────────
    print("── GRU / LSTM predictions (pre-trained weights) ───────────────")
    for split in ("train", "val"):
        generate_torch_split("gru",  GRUModel,  df, gru_vocab,  split)
        generate_torch_split("lstm", LSTMModel, df, lstm_vocab, split)

    # ── NB: OOF for train (unbiased), full-fit for val ────────────────────────
    print("\n── NB predictions ─────────────────────────────────────────────")
    generate_oof_nb(df)
    generate_nb_val(df)

    print("\n" + "=" * 65)
    print("Done. Delete existing CSVs and re-run to regenerate.")
    print("=" * 65)
